import{b as d,O as e,g as r,j as a}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"性能测试用例规范","description":"","frontmatter":{},"headers":[],"relativePath":"performance/appendix/test-case-spec/index.md","filePath":"性能测试/6.附录/性能测试用例规范.md","lastUpdated":1781755252000}'),n={name:"performance/appendix/test-case-spec/index.md"};function o(s,t,l,h,i,c){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h1 id="性能测试用例规范" tabindex="-1">性能测试用例规范 <a class="header-anchor" href="#性能测试用例规范" aria-label="Permalink to &quot;性能测试用例规范&quot;">​</a></h1><blockquote><p>一句话：性能测试用例不看&quot;对不对&quot;，看&quot;快不快、扛不扛得住&quot;。</p></blockquote><h2 id="先看一个对比" tabindex="-1">先看一个对比 <a class="header-anchor" href="#先看一个对比" aria-label="Permalink to &quot;先看一个对比&quot;">​</a></h2><p>功能测试和性能测试的用例，长得完全不一样。举个例子感受一下：</p><p><strong>功能测试用例（你熟悉的）：</strong></p><blockquote><p>输入正确账号密码 → 点击登录 → 断言&quot;跳转到首页&quot;</p></blockquote><p><strong>性能测试用例（这次要学的）：</strong></p><blockquote><p>200 人同时登录 → 持续 10 分钟 → P99 响应时间 ≤ 500ms，错误率 ≤ 0.1%</p></blockquote><p>看出来了吗？功能用例问的是 <strong>&quot;对不对&quot;</strong>（布尔值，pass/fail），性能用例问的是 <strong>&quot;扛不扛得住&quot;</strong>（数值对比，实际 vs 阈值）。</p><h2 id="一、和功能用例的本质区别" tabindex="-1">一、和功能用例的本质区别 <a class="header-anchor" href="#一、和功能用例的本质区别" aria-label="Permalink to &quot;一、和功能用例的本质区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>功能测试</th><th>性能测试</th></tr></thead><tbody><tr><td>核心问题</td><td>功能对不对？</td><td>系统快不快、能扛多少人？</td></tr><tr><td>验证方式</td><td>断言单个操作的结果</td><td>统计一段时间内大量操作的数值</td></tr><tr><td>结果类型</td><td>布尔值（pass / fail）</td><td>数值对比（实际 ≤ 阈值？）</td></tr><tr><td>执行一次够吗</td><td>够，一条用例跑一次就知道过没过</td><td>不够，要压够时间才有统计意义</td></tr><tr><td>频率</td><td>每次提 PR / 每日回归</td><td>发版前 / 大促前 / 按周</td></tr><tr><td>环境要求</td><td>测试环境即可</td><td>最好独立压测环境，避免影响他人</td></tr></tbody></table><blockquote><p><strong>关键认知：</strong> 功能测试通过 ≠ 性能没问题。1000 个功能用例全绿，上线 200 人同时用照样可能崩。</p></blockquote><h2 id="二、核心指标速览" tabindex="-1">二、核心指标速览 <a class="header-anchor" href="#二、核心指标速览" aria-label="Permalink to &quot;二、核心指标速览&quot;">​</a></h2><p>写性能用例前，先认识几个一定会用到的指标。详细解读见 <a href="/performance/appendix/baseline.html">性能测试基准</a>，这里只列&quot;用例里怎么写&quot;：</p><table tabindex="0"><thead><tr><th>指标</th><th>口语化理解</th><th>用例里怎么用</th></tr></thead><tbody><tr><td><strong>平均 RT</strong></td><td>大部分请求要等多久</td><td>阈值例：≤ 200ms</td></tr><tr><td><strong>P95 RT</strong></td><td>95% 的人最慢等多久</td><td>比平均值重要，阈值例：≤ 500ms</td></tr><tr><td><strong>P99 RT</strong></td><td>最慢那 5% 里更慢的那部分</td><td>长尾重点盯，阈值例：≤ 1s</td></tr><tr><td><strong>QPS / TPS</strong></td><td>每秒能处理多少请求/事务</td><td>不低于基线值，越高越好</td></tr><tr><td><strong>错误率</strong></td><td>100 个请求里有几个挂了</td><td>阈值：≤ 0.1%（压测中必须接近 0%）</td></tr><tr><td><strong>CPU / 内存</strong></td><td>服务器累不累</td><td>阈值：CPU &lt; 70%、内存 &lt; 80% 且不持续涨</td></tr><tr><td><strong>FCP / LCP</strong></td><td>用户看到页面的第一眼印象</td><td>前端用例专属，阈值例：FCP ≤ 1.5s</td></tr></tbody></table><blockquote><p><strong>P99 比平均值重要十倍。</strong> 平均值 300ms 很漂亮，但如果 P99 是 5 秒，意味着每 100 个用户就有 1 个卡了 5 秒——他可能已经关页面了。</p></blockquote><h2 id="三、用例字段说明" tabindex="-1">三、用例字段说明 <a class="header-anchor" href="#三、用例字段说明" aria-label="Permalink to &quot;三、用例字段说明&quot;">​</a></h2><h3 id="_3-1-完整版-11-列" tabindex="-1">3.1 完整版（11 列） <a class="header-anchor" href="#_3-1-完整版-11-列" aria-label="Permalink to &quot;3.1 完整版（11 列）&quot;">​</a></h3><p>适合正式项目，覆盖&quot;执行前怎么配 + 执行后怎么判&quot;的全流程。</p><table tabindex="0"><thead><tr><th>列名</th><th style="text-align:center;">必填</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td>序号</td><td style="text-align:center;">✅</td><td>唯一编号，方便引用和追溯</td><td>PT-001</td></tr><tr><td>场景名称</td><td style="text-align:center;">✅</td><td>一句话说清测什么业务</td><td>登录接口并发</td></tr><tr><td>场景描述</td><td style="text-align:center;">✅</td><td>模拟怎样的用户行为</td><td>200 用户同时打开登录页输入账号密码并点击登录</td></tr><tr><td>并发数</td><td style="text-align:center;">✅</td><td>模拟多少用户/VU 同时操作</td><td>200</td></tr><tr><td>持续时间</td><td style="text-align:center;">✅</td><td>压多久（含预热时间）</td><td>10min</td></tr><tr><td>压测目标</td><td style="text-align:center;">✅</td><td>具体接口 URL 或页面路径</td><td><code>POST /api/auth/login</code></td></tr><tr><td>关注指标</td><td style="text-align:center;">✅</td><td>这次压测盯哪个数值</td><td>P99 响应时间</td></tr><tr><td>阈值</td><td style="text-align:center;">✅</td><td>达标线，不达标记不通过</td><td>≤ 500ms</td></tr><tr><td>实际结果</td><td style="text-align:center;">—</td><td>跑完再填，跑出来的真实数值</td><td>P99 = 320ms</td></tr><tr><td>结论</td><td style="text-align:center;">—</td><td>跑完再填，达标还是挂了</td><td>✅ 达标</td></tr><tr><td>备注</td><td style="text-align:center;">选填</td><td>环境、数据、特殊说明</td><td>用测试账号，避免污染</td></tr></tbody></table><h3 id="_3-2-最小够用版-7-列" tabindex="-1">3.2 最小够用版（7 列） <a class="header-anchor" href="#_3-2-最小够用版-7-列" aria-label="Permalink to &quot;3.2 最小够用版（7 列）&quot;">​</a></h3><p>日常快速压测、小团队敏捷项目，够用就好：</p><table tabindex="0"><thead><tr><th>列名</th><th style="text-align:center;">必填</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td>序号</td><td style="text-align:center;">✅</td><td>唯一编号</td><td>PT-001</td></tr><tr><td>场景名称</td><td style="text-align:center;">✅</td><td>测什么</td><td>登录接口并发</td></tr><tr><td>并发数</td><td style="text-align:center;">✅</td><td>多少人同时压</td><td>200</td></tr><tr><td>持续时间</td><td style="text-align:center;">✅</td><td>压多久</td><td>10min</td></tr><tr><td>压测目标</td><td style="text-align:center;">✅</td><td>压哪个接口/页面</td><td><code>POST /api/auth/login</code></td></tr><tr><td>关注指标 + 阈值</td><td style="text-align:center;">✅</td><td>盯什么 + 达标线</td><td>P99 RT ≤ 500ms</td></tr><tr><td>结论</td><td style="text-align:center;">—</td><td>跑完填</td><td>✅ 达标</td></tr></tbody></table><blockquote><p>完整版把「指标」和「阈值」拆两列，方便统计和筛选；最小版合二为一，写起来更快。选哪个看团队规模和流程要求。</p></blockquote><h3 id="_3-3-字段关键说明" tabindex="-1">3.3 字段关键说明 <a class="header-anchor" href="#_3-3-字段关键说明" aria-label="Permalink to &quot;3.3 字段关键说明&quot;">​</a></h3><p><strong>并发数不是拍脑袋填的。</strong> 从线上数据推算：日活 10000 人，假设 20% 集中在早晚高峰的 1 小时内，则高峰期在线约 2000 人。实际同时发请求的通常只有 10%~30%，即 200~600 并发。取中位数 300 作为并发目标。</p><p><strong>持续时间不能太短。</strong> 压 1 分钟看不出问题——CPU 还没打满、缓存还没热、GC 还没触发。一般接口至少 5 分钟，稳定性测试至少 2 小时。</p><p><strong>阈值从基线来，不凭空定。</strong> 先做一次基准测试拿到实际值，设为基线；后续压测和基线对比，不只看绝对值。</p><h2 id="四、测试用例示例" tabindex="-1">四、测试用例示例 <a class="header-anchor" href="#四、测试用例示例" aria-label="Permalink to &quot;四、测试用例示例&quot;">​</a></h2><blockquote><p>每个类型选典型场景作为示例。实际项目按需扩展。</p></blockquote><h3 id="_4-1-接口压测" tabindex="-1">4.1 接口压测 <a class="header-anchor" href="#_4-1-接口压测" aria-label="Permalink to &quot;4.1 接口压测&quot;">​</a></h3><table tabindex="0"><thead><tr><th>序号</th><th>场景名称</th><th style="text-align:center;">并发数</th><th>持续时间</th><th>压测目标</th><th>关注指标 + 阈值</th><th style="text-align:center;">结论</th></tr></thead><tbody><tr><td>PT-001</td><td>登录接口基准</td><td style="text-align:center;">1</td><td>2min</td><td><code>POST /api/auth/login</code></td><td>平均 RT ≤ 100ms</td><td style="text-align:center;"></td></tr><tr><td>PT-002</td><td>登录接口并发</td><td style="text-align:center;">200</td><td>10min</td><td><code>POST /api/auth/login</code></td><td>P99 RT ≤ 500ms</td><td style="text-align:center;"></td></tr><tr><td>PT-003</td><td>登录接口并发</td><td style="text-align:center;">200</td><td>10min</td><td><code>POST /api/auth/login</code></td><td>错误率 ≤ 0.1%</td><td style="text-align:center;"></td></tr><tr><td>PT-004</td><td>登录接口极限</td><td style="text-align:center;">500+</td><td>渐进加压</td><td><code>POST /api/auth/login</code></td><td>QPS ≥ 500</td><td style="text-align:center;"></td></tr><tr><td>PT-005</td><td>列表分页查询</td><td style="text-align:center;">100</td><td>5min</td><td><code>GET /api/tasks?page=1</code></td><td>P95 RT ≤ 300ms</td><td style="text-align:center;"></td></tr><tr><td>PT-006</td><td>提交评价并发</td><td style="text-align:center;">50</td><td>5min</td><td><code>POST /api/reviews</code></td><td>错误率 ≤ 0.1%</td><td style="text-align:center;"></td></tr><tr><td>PT-007</td><td>提交评价并发</td><td style="text-align:center;">50</td><td>5min</td><td><code>POST /api/reviews</code></td><td>P99 RT ≤ 1s</td><td style="text-align:center;"></td></tr></tbody></table><blockquote><p>PT-002 和 PT-003 是同一个场景拆了两个指标来写。拆开的好处是每个指标单独判定，不会因为 P99 过了就漏看错误率。</p></blockquote><h3 id="_4-2-前端页面性能" tabindex="-1">4.2 前端页面性能 <a class="header-anchor" href="#_4-2-前端页面性能" aria-label="Permalink to &quot;4.2 前端页面性能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>序号</th><th>场景名称</th><th>网络条件</th><th>压测目标</th><th>关注指标 + 阈值</th><th style="text-align:center;">结论</th></tr></thead><tbody><tr><td>PT-101</td><td>首页冷启动</td><td>4G</td><td><code>/home</code></td><td>FCP ≤ 1.5s</td><td style="text-align:center;"></td></tr><tr><td>PT-102</td><td>列表页大数据量</td><td>4G</td><td><code>/admin-page</code></td><td>TTI ≤ 3s</td><td style="text-align:center;"></td></tr><tr><td>PT-103</td><td>列表页滚动流畅</td><td>—</td><td><code>/admin-page</code></td><td>帧率 ≥ 30fps</td><td style="text-align:center;"></td></tr><tr><td>PT-104</td><td>首页弱网体验</td><td>3G</td><td><code>/home</code></td><td>FCP ≤ 3s</td><td style="text-align:center;"></td></tr></tbody></table><h3 id="_4-3-稳定性-耐久" tabindex="-1">4.3 稳定性 / 耐久 <a class="header-anchor" href="#_4-3-稳定性-耐久" aria-label="Permalink to &quot;4.3 稳定性 / 耐久&quot;">​</a></h3><table tabindex="0"><thead><tr><th>序号</th><th>场景名称</th><th style="text-align:center;">并发数</th><th>持续时间</th><th>压测目标</th><th>关注指标 + 阈值</th><th style="text-align:center;">结论</th></tr></thead><tbody><tr><td>PT-201</td><td>日常负载浸泡</td><td style="text-align:center;">50</td><td>24h</td><td>全量核心接口</td><td>错误率 ≤ 0.1%</td><td style="text-align:center;"></td></tr><tr><td>PT-202</td><td>日常负载浸泡</td><td style="text-align:center;">50</td><td>24h</td><td>全量核心接口</td><td>内存无持续增长</td><td style="text-align:center;"></td></tr></tbody></table><blockquote><p>浸泡测试的核心目的是抓<strong>内存泄漏</strong>。前 1 小时正常不代表 24 小时正常——内存只涨不跌，最终 OOM。</p></blockquote><h2 id="五、执行策略" tabindex="-1">五、执行策略 <a class="header-anchor" href="#五、执行策略" aria-label="Permalink to &quot;五、执行策略&quot;">​</a></h2><p>不是每次都要全跑一遍。按阶段分，该跑的跑，不该跑的别浪费机器：</p><table tabindex="0"><thead><tr><th>阶段</th><th>什么时候跑</th><th>跑什么</th><th>通过标准</th></tr></thead><tbody><tr><td><strong>基准测试</strong></td><td>功能开发完就跑</td><td>单用户单接口 RT</td><td>无异常慢接口（对比基线）</td></tr><tr><td><strong>并发测试</strong></td><td>提测前 / 每日凌晨</td><td>核心接口 P0 场景</td><td>全部指标达标</td></tr><tr><td><strong>极限测试</strong></td><td>发版前</td><td>摸天花板 QPS</td><td>不低于上次基线的 10%</td></tr><tr><td><strong>浸泡测试</strong></td><td>大版本发布前</td><td>24h 日常负载</td><td>错误率不超标，内存不泄漏</td></tr><tr><td><strong>前端性能</strong></td><td>页面大改后</td><td>Lighthouse 报告</td><td>分数不低于上次基线</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>功能开发完 → 基准测试（确认&quot;没写慢&quot;）</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>提测前     → 并发测试（确认&quot;扛得住&quot;）</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>发版前     → 极限测试 + 浸泡（确认&quot;天花板在哪、会不会漏&quot;）</span></span></code></pre></div><blockquote><p><strong>原则：先基准再并发。</strong> 单用户 RT 都不达标，加并发没有任何意义——只会把问题放大。</p></blockquote><h2 id="六、压测工具怎么选" tabindex="-1">六、压测工具怎么选 <a class="header-anchor" href="#六、压测工具怎么选" aria-label="Permalink to &quot;六、压测工具怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>一句话</th><th>适合谁</th></tr></thead><tbody><tr><td><strong>k6</strong></td><td>JS 写脚本、CLI 跑、Grafana 出图</td><td>前端/全栈开发，CI 集成首选</td></tr><tr><td><strong>JMeter</strong></td><td>GUI 编排 + 插件生态，老牌全能</td><td>专职测试、复杂场景</td></tr><tr><td><strong>wrk / wrk2</strong></td><td>命令行一行跑，极轻量</td><td>开发自测、快速摸底</td></tr><tr><td><strong>Locust</strong></td><td>Python 写脚本，分布式原生支持</td><td>Python 技术栈团队</td></tr><tr><td><strong>Lighthouse</strong></td><td>Chrome 内置，前端性能跑分</td><td>前端开发，页面优化</td></tr><tr><td><strong>WebPageTest</strong></td><td>全球多节点，详细瀑布图</td><td>多地域用户体验评估</td></tr></tbody></table><blockquote><p>如果只会选一个：<strong>接口压测选 k6</strong>（脚本即代码，CI 友好），<strong>前端性能选 Lighthouse</strong>（Chrome 自带，零安装）。</p></blockquote><h2 id="七、最佳实践" tabindex="-1">七、最佳实践 <a class="header-anchor" href="#七、最佳实践" aria-label="Permalink to &quot;七、最佳实践&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>为什么</th><th>怎么做</th></tr></thead><tbody><tr><td><strong>先基准再并发</strong></td><td>单用户慢→并发更慢，问题放大</td><td>第一步永远是 PT-001</td></tr><tr><td><strong>阈值从基线来</strong></td><td>凭空定 200ms 可能根本达不到</td><td>先跑一次基准，记录实际值作为基线</td></tr><tr><td><strong>隔离环境</strong></td><td>压测会把服务器打满</td><td>独立压测环境，不对生产/共用环境操作</td></tr><tr><td><strong>数据脱敏</strong></td><td>压测数据可能被日志记录</td><td>不用真实用户数据，用测试账号</td></tr><tr><td><strong>盯 P99 不盯平均</strong></td><td>平均值掩盖抖动</td><td>用例里 P99 必写，平均值可选</td></tr><tr><td><strong>监控不光看被测</strong></td><td>接口快但 DB 慢查询爆炸也是失败</td><td>服务器 CPU/内存/DB 慢查询一起看</td></tr><tr><td><strong>结论可追溯</strong></td><td>单次绝对值没意义</td><td>每次记录实际值，形成趋势图</td></tr></tbody></table><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ul><li>性能用例和功能用例<strong>写法完全不同</strong>——前者看数值是否达标，后者看操作是否正确</li><li>用例核心 7 个字段：<strong>序号、场景、并发数、持续时间、压测目标、指标+阈值、结论</strong></li><li><strong>P99 比平均值重要十倍</strong>，用例里必写</li><li>不是每次都全跑：<strong>基准→并发→极限→浸泡</strong>，逐级递进</li><li>阈值不要凭空定，从基线来</li></ul>`,50)])])}const p=d(n,[["render",o]]);export{b as __pageData,p as default};
